while read -r url; do
  for i in {1..3}; do
    if curl -m 10 --retry 3 --retry-delay 5 -sSL "$url" -o "$(basename "$url")"; then
      sha256sum "$(basename "$url")" | awk '{print "$url $1"}' >> checksums.txt;
      break;
    fi;
  done;
done < urls.txt

