while read -r url; do
  for i in {1..3}; do
    if curl -m 10 --retry 0 --retry-delay 0 --retry-connrefused --retry-all-errors --retry-keep-alive --retry-protocol=retry -sSL "$url" -o "$(basename "$url")" -w "%{http_code}" -o /dev/null; then
      sha256sum "$(basename "$url")" | awk '{print \"$url\\t$1\"}' >> checksums.txt;
      break;
    fi;
  done;
done < urls

expected:
git_rebase_and_push() {
  local branch=$1 prev=$(git rev-parse --abbrev-ref HEAD)
  git checkout "$branch" && git fetch origin && git rebase origin/main && make test && git push origin "$branch" || { git rebase --abort; git checkout "$prev"; }
}

command:
archive_latest(){
  dir="${1:-.}"
  ext="${2:-.txt}"
  n=${3:-10}
  archive="${dir%/}_$(date +%Y%m%d_%H%M%S).zip"
  find "$dir" -type f -name "*.$ext" -printf "%T@ %p\n" | sort -nr | head -n "$n" | cut -d' ' -f2- | xargs -I{} zip -@ "$archive"
}

size_of_ext(){
  dir="$1"
  ext="$2"
  size=$(find "$dir" -type f -name "*.$ext" -exec du -sm {} + | awk '{s+=$1} END {print s}')
  printf "%.3f MB\n" "$size"
}

