#!/usr/bin/env bash
awk '{print $9}' /var/log/apache2/access.log | sort | uniq -c | while read count code; do
  printf "%s %s | ", $code, $count;
  for ((i=0;i<$count;i++)); do echo -n '*'; done;
  echo;
done

